import { NavLink } from 'react-router-dom';
import s from './NavBar.module.css';
import chat from '../../assets/images/icons8-message.svg'
import foundUsers from '../../assets/images/multiple-users-silhouette.png'
import newspaper from '../../assets/images/newspaper.png'
import setting from '../../assets/images/setting.png'
import song from '../../assets/images/icons8-song.svg'
import profile from '../../assets/images/profile.png'


const NavBar = (props) => {
    const getLinkClass = ({ isActive }) => {
    return isActive ? `${s.item} ${s.active}`: s.item;
  };
  return (
    <nav className={s.nav}>
      <div className={s.item}>
        <img alt='' src={profile} className={s.img}/>
        <NavLink to="/profile" className={getLinkClass}>Profile</NavLink>
      </div>
      <div className={s.item}>
        <img alt='' src={chat} className={s.img}/>
        <NavLink to="/dialogs" className={getLinkClass}>Message</NavLink>
      </div>
      <div className={s.item}>
        <img alt='' src={newspaper} className={s.img}/>
        <NavLink to="/News" className={getLinkClass}>News</NavLink>
      </div>
      <div className={s.item}>
        <img alt='' src={song} className={s.img}/>
        <NavLink to="/music" className={getLinkClass}>Music</NavLink>
      </div>
      <div className={s.item}>
        <img alt='' src={setting} className={s.img}/>
        <NavLink to="/settings" className={getLinkClass}>Settings</NavLink>
      </div>
      <div className={s.item}>
        <img alt='' src={foundUsers} className={s.img}/>
        <NavLink to="/users" className={getLinkClass}>New Users</NavLink>
      </div>
    </nav>);
}

export default NavBar;