import React from 'react'
import { NavLink } from 'react-router-dom'
import userPhoto from '../../assets/images/user.png'
import s from './Users.module.css'

let User = ({ user, followingInProgress, unfollow, follow }) => {
    const isFollowing = user.followed
    const isLoading = followingInProgress.some(id => id === user.id)

    return (
        <div className={s.userCard}>

            <NavLink to={'/profile/' + user.id} className={s.avatarLink}>
                <img
                    src={user.photos.small != null ? user.photos.small : userPhoto}
                    className={s.avatar}
                    alt="user avatar"
                />
            </NavLink>

            <div className={s.userInfo}>

                <NavLink
                    to={'/profile/' + user.id}
                    className={s.userName}
                >
                    {user.name}
                </NavLink>

                <div className={s.status}>
                    {user.status || 'No status'}
                </div>

                <div className={s.location}>
                    <span>{user.location?.country || 'Unknown country'}</span>
                    <span>{user.location?.city || 'Unknown city'}</span>
                </div>

            </div>

            <button
                className={`${s.followButton} ${
                    isFollowing ? s.following : ''
                }`}
                disabled={isLoading}
                onClick={() => {
                    if (isFollowing) {
                        unfollow(user.id)
                    } else {
                        follow(user.id)
                    }
                }}
            >
                {isLoading
                    ? '...'
                    : isFollowing
                        ? 'Unfollow'
                        : 'Follow'
                }
            </button>

        </div>
    )
}

export default User